def I(n,c='w-5 h-5',fill=False,label=None):
    a=f'role="img" aria-label="{label}"' if label else 'aria-hidden="true"'
    return f'<svg {a} class="{c} shrink-0" viewBox="0 0 24 24" fill="{"currentColor" if fill else "none"}" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">{P[n]}</svg>'
