HUB={'Alta Córdoba':7,'Alberdi':5,'Gral. Pueyrredón':4,'Argüello':3,'Villa Belgrano':3}
N=[f'[Nombre del salón {i}]' for i in range(1,10)]
def crumbs(items):
    li=''.join(f'<li><a class="ulink" href="#">{i}</a><span aria-hidden="true" class="mx-2 text-ink-300">/</span></li>' for i in items[:-1])
    return f'<nav aria-label="Migas de pan" class="text-sm text-ink-500"><ol class="flex flex-wrap">{li}<li aria-current="page" class="text-ink-900 font-bold">{items[-1]}</li></ol></nav>'
def btn(t,ic=None,cls=''): return f'<a href="#" class="inline-flex items-center justify-center gap-2 h-12 px-5 rounded-[4px] bg-brand-700 hover:bg-brand-800 text-white font-bold {cls}">{t}{I(ic,"w-4 h-4") if ic else ""}</a>'
def more(t,cls=''): return f'<a href="#" class="ulink inline-flex items-center gap-2 font-bold text-brand-800 {cls}">{t}{I("arrow","w-4 h-4")}</a>'
def open_(o=True): return f'<span class="font-bold text-brand-800">Abierto</span> hasta [20:00]' if o else '<span class="font-bold text-danger-700">Cerrado</span>, abre [mañana 10:00]'
# ---------- fila de listado
def row(i,f=True,v=False,o=True,tel=True,b=None):
    pr=f'<p class="text-sm"><span class="num text-lg font-semibold">$[min]–[max]</span> por niño <span class="text-ink-500">· verificado [12/10/2026]</span></p>' if v else '<p class="text-sm text-ink-500">Precio sin cargar</p>'
    return f'''<article class="relative grid grid-cols-[2.25rem_6.5rem_1fr] md:grid-cols-[3rem_10rem_1fr] gap-3 md:gap-5 py-5 border-t border-ink-200 group">
<span class="num text-2xl md:text-3xl text-brand-700 leading-none pt-1">{i:02d}</span>{pic(i,"aspect-[4/5] md:aspect-[4/3] w-full",f,credit=False)}
<div class="min-w-0 grid gap-1 content-start"><p class="kicker text-ink-500">Salón infantil · {b or BAR[i%5]}</p>
<h3 class="font-display text-xl md:text-2xl font-medium leading-tight"><a href="#" class="group-hover:text-brand-800 after:absolute after:inset-0">{N[i-1]}</a></h3>
<div class="flex flex-wrap items-center gap-x-3 gap-y-1">{rating(4.8-i*.1,140-i*9)}{'<span class="tag tag-v">'+I("check","w-3.5 h-3.5")+'Verificado</span>' if v else ''}</div>
<p class="text-sm text-ink-700 flex items-center gap-1.5">{I("clock","w-4 h-4 text-ink-500")}{open_(o)}</p>{pr}
<p class="text-xs text-ink-500 flex items-center gap-1.5">{(I("phone","w-3.5 h-3.5")+"Con teléfono · ") if tel else ""}Datos de Google</p></div></article>'''
def fbtn(t,on=False,f2=False,ic=None):
    if f2: return f'<li><span aria-disabled="true" class="inline-flex items-center gap-2 h-10 px-3 text-sm text-ink-500 border border-dashed border-ink-300 rounded-[4px] whitespace-nowrap">{t}<span class="kicker text-sun-800 text-xs">fase 2</span></span></li>'
    return f'<li><button aria-pressed="{str(on).lower()}" class="inline-flex items-center gap-2 h-10 px-3 text-sm font-bold rounded-[4px] whitespace-nowrap border {"border-ink-900 bg-ink-900 text-white" if on else "border-ink-300 bg-white hover:border-brand-700"}">{I(ic,"w-4 h-4") if ic else ""}{(I("tick","w-4 h-4") if on and not ic else "")}{t}</button></li>'
def filterbar(b=None):
    return '<ul class="flex gap-2 overflow-x-auto pb-1" aria-label="Filtros">'+fbtn('Filtros',ic='sliders')+fbtn(f'Barrio: {b}' if b else 'Barrio',bool(b))+fbtn('Salón infantil',True)+fbtn('Pelotero e inflables')+fbtn('Salón de eventos')+fbtn('4 o más')+fbtn('Abierto ahora',True)+fbtn('Con teléfono')+fbtn('Cerca mío',ic='locate')+''.join(fbtn(t,f2=True) for t in ['Precio','Capacidad','Edades','Servicios','Verificado'])+'</ul>'
def mapa(cls='',btns=True,np=8):
    pins=''.join(f'<span class="absolute -translate-x-1/2 -translate-y-full flex flex-col items-center" style="left:{x}%;top:{y}%"><span class="num grid place-items-center w-7 h-7 bg-brand-700 text-white text-sm rounded-[3px]">{n}</span><span class="w-px h-2 bg-brand-700"></span></span>' for n,(x,y) in enumerate([(22,30),(45,22),(62,50),(30,64),(74,34),(54,78),(84,62),(14,80)][:np] if np>1 else [(50,58)],1))
    pos='' if 'absolute' in cls else 'relative '
    return f'<div class="{pos}overflow-hidden bg-[#EEF1E6] border border-ink-200 {cls}" role="region" aria-label="Mapa de resultados"><svg aria-hidden="true" class="absolute inset-0 w-full h-full" preserveAspectRatio="none" viewBox="0 0 100 100"><path d="M0 40 L100 28 M0 70 L100 62 M30 0 L38 100 M68 0 L60 100 M0 12 L100 88" stroke="#fff" stroke-width="1.2"/><path d="M-5 55 C20 45 40 60 60 48 S90 40 105 50" stroke="#C7D6E8" stroke-width="3" fill="none"/></svg>{pins}'+(f'<button class="absolute top-3 left-3 inline-flex items-center gap-2 h-10 px-3 bg-white border border-ink-300 rounded-[4px] text-sm font-bold">{I("search","w-4 h-4")}Buscar en esta zona</button>' if btns else '')+'<span class="absolute bottom-1 right-2 text-[10px] text-ink-700">[Map data © Google]</span></div>'
def toggle(): return f'<div class="lg:hidden fixed bottom-4 left-1/2 -translate-x-1/2 z-10 grid grid-cols-2 bg-ink-900 text-white rounded-[4px] overflow-hidden" role="group" aria-label="Vista"><button aria-pressed="true" class="flex items-center gap-2 h-12 px-5 bg-white text-ink-900 font-bold">{I("list","w-4 h-4")}Lista</button><button aria-pressed="false" class="flex items-center gap-2 h-12 px-5 font-bold">{I("map","w-4 h-4")}Mapa</button></div>'
def faq(): return '<section class="mt-14"><p class="kicker text-brand-800">Preguntas</p><h2 class="font-display text-3xl font-medium mb-2">Preguntas frecuentes</h2>'+''.join(f'<details class="border-t border-ink-200 py-4"><summary class="cursor-pointer font-bold flex justify-between items-center"><span><span class="num text-brand-700 mr-3">{n:02d}</span>[Pregunta {n}]</span>{I("down","w-4 h-4")}</summary><p class="text-ink-700 mt-2 pl-9">[Respuesta]</p></details>' for n in (1,2,3))+'</section>'
OTROS=[('A',[('Alto Alberdi',2),('Altos de Vélez Sarsfield',1),('Ampliación Residencial América',1),('Ayacucho',1)]),('B',[('Barrio Jardín',2),('Bella Vista',1),('Bajo Palermo',1)]),('C',[('Centro',2),('Cerro de las Rosas',2),('Cofico',1),('Colinas de Vélez Sarsfield',1),('Crisol',1)]),('G',[('General Bustos',2),('General Paz',2),('Güemes',1)]),('J',[('Jardín Espinosa',1),('Juniors',1)]),('L',[('Las Margaritas',1),('Los Boulevares',1),('Los Naranjos',1)]),('M',[('Maipú',1),('Marqués de Sobremonte',2),('Matienzo',1)]),('N',[('Nueva Córdoba',2)]),('O',[('Observatorio',1)]),('P',[('Parque Capital',1),('Parque Liceo',1),('Poeta Lugones',1),('Providencia',1)]),('R',[('Residencial San Carlos',1),('Rogelio Martínez',1)]),('S',[('San Martín',1),('San Vicente',1),('Santa Isabel',1)]),('U',[('Urca',1)]),('V',[('Villa Cabrera',1),('Villa El Libertador',1)]),('Y',[('Yofre',1)])]
def otros():
    letras=''.join(f'<li><a href="#ob-{l}" class="num grid place-items-center w-9 h-9 border border-ink-200 rounded-[2px] text-sm font-semibold hover:border-brand-700">{l}</a></li>' for l,_ in OTROS)
    grupos=''.join(f'<div class="break-inside-avoid mb-5" id="ob-{l}"><p class="num text-2xl text-brand-700 leading-none border-b border-ink-900/80 pb-1">{l}</p><ul class="text-sm">'+''.join(f'<li class="flex justify-between gap-3 border-b border-ink-200 py-1.5"><a href="#" class="hover:text-brand-800">{n}</a><span class="num text-ink-500">{c}</span></li>' for n,c in xs)+'</ul></div>' for l,xs in OTROS)
    return f'<section class="mt-12 border-t border-ink-900/80 pt-4" aria-labelledby="ob"><div class="flex flex-wrap items-baseline justify-between gap-3"><div><p class="kicker text-ink-500">Índice de barrios</p><h2 id="ob" class="font-display text-2xl md:text-3xl font-medium">Otros barrios <span class="num text-ink-500">[n]</span></h2></div><p class="text-sm text-ink-700 max-w-sm">[Barrios con 1 o 2 salones. Sin página propia: cada uno filtra este listado]</p></div><nav aria-label="Saltar a letra" class="mt-4"><ul class="flex flex-wrap gap-1.5">{letras}</ul></nav><div class="mt-6 columns-2 md:columns-3 gap-6">{grupos}</div></section>'
def listado(title,cr,b=None,chicos=True):
    nr=3 if b else 6
    rows=''.join(row(i,f=i!=3,v=i==2,o=i!=4,tel=i!=5,b=b) for i in range(1,nr+1))
    if b: rows+=f'<section class="mt-10 border-t border-ink-900/80 pt-4" aria-labelledby="bc"><p class="kicker text-ink-500">A menos de 2 km</p><h2 id="bc" class="font-display text-2xl md:text-3xl font-medium">Salones en barrios cercanos</h2><p class="text-sm text-ink-700 mt-1">[Texto placeholder: completa la búsqueda cuando el barrio tiene pocas fichas]</p></section>'+''.join(row(i,f=i!=5,o=True,b=x).replace(f'>{i:02d}<',f'>{i:02d}<',1) for i,x in [(4,'General Bustos'),(5,'Cofico'),(6,'Alto Alberdi')])+'<div class="py-5 border-t border-ink-200">'+more('Ver los [n] salones de Córdoba Capital')+'</div>'
    barrios='<nav aria-label="Barrios" class="mt-4"><ul class="flex flex-wrap gap-x-5 gap-y-1 text-sm">'+''.join(f'<li><a href="#" {"aria-current=page" if x==b else ""} class="ulink {"font-bold text-brand-800" if x==b else "decoration-ink-300"}">{x} <span class="text-ink-500">[n]</span></a></li>' for x in BAR)+'</ul></nav>'
    ch=otros() if chicos else ''
