    A=''.join(f'<a href="#" class="flex flex-col items-center justify-center gap-1.5 h-[72px] text-sm font-bold {"hover:bg-brand-50 text-ink-900" if on else "text-ink-300 pointer-events-none"} border-r last:border-r-0 border-ink-200" {"" if on else "aria-disabled=true"}>{I(ic)}{t}{"" if on else "<span class=sr-only> (no disponible)</span>"}</a>' for ic,t,on in acts)
    acts_box=f'<div class="grid grid-cols-4 border-y border-ink-900/80">{A}</div>'
    if v:
        items=[('Precio por niño','$[min]–[max]',None),('Invitados','[15]–[60]','users'),('Duración','[3 h]','clock'),('Edades','[2 a 10 años]','cake'),('Capacidad','[80 personas]','users'),('Estacionamiento','[Sí]','park'),('Accesibilidad','[Rampa y baño adaptado]','access'),('Instagram','<a class="ulink" href="#">@[usuario]</a>','ig')]
        svc='<dl class="grid grid-cols-2 md:grid-cols-4 border-t border-ink-200">'+''.join(f'<div class="py-4 pr-3 border-b border-ink-200"><dt class="kicker text-ink-500 flex items-center gap-1.5">{I(ic,"w-4 h-4") if ic else ""}{k}</dt><dd class="{"num text-2xl" if k.startswith("Precio") else "font-bold"} mt-1">{val}</dd></div>' for k,val,ic in items)+'</dl><h3 class="font-display text-xl mt-6">Qué incluye</h3><ul class="mt-2 grid md:grid-cols-2 gap-x-8">'+''.join(f'<li class="flex gap-2 py-2 border-b border-ink-200">{I("tick","w-4 h-4 text-brand-700 mt-1")}[Ítem {k}]</li>' for k in range(1,5))+'</ul>'
        desc='<p class="text-lg text-ink-700 max-w-prose">[Descripción cargada por el dueño]</p><p class="kicker text-ink-500 mt-2">Información del salón · actualizada [fecha]</p>'
        badge=f'<span class="tag tag-v">{I("check","w-3.5 h-3.5")}Precio verificado el [12/10/2026]</span><span class="tag">Ficha reclamada</span>'
    else:
        svc=f'<div class="relative border border-brand-700 bg-brand-50 p-6 md:p-8 overflow-hidden">{conf("absolute -right-6 -top-4 w-56 opacity-80")}<p class="kicker text-brand-800">Para dueños</p><p class="font-display text-2xl md:text-3xl font-medium mt-1 max-w-md">¿Es tu salón? Cargá tus precios</p><p class="text-ink-700 mt-2 max-w-md">[Beneficios de reclamar la ficha]</p>{btn("Reclamar ficha gratis","arrow","mt-4")}</div><dl class="mt-6 grid grid-cols-2 md:grid-cols-3 border-t border-ink-200 text-sm">'+''.join(f'<div class="py-3 border-b border-ink-200"><dt class="kicker text-ink-500">{k}</dt><dd class="text-ink-500 italic">sin dato</dd></div>' for k in ['Precio por niño','Invitados','Duración','Edades','Capacidad','Estacionamiento'])+'</dl>'
        desc='<p class="text-ink-500 italic">[Sin descripción del dueño]</p>'; badge=''
    hrs='<table class="w-full text-sm"><caption class="sr-only">Horarios</caption><tbody>'+''.join(f'<tr class="border-b border-ink-200 {"font-bold text-brand-800" if d=="Miércoles" else ""}"><th scope="row" class="text-left font-normal py-2">{d}{" (hoy)" if d=="Miércoles" else ""}</th><td class="text-right num">[10:00–20:00]</td></tr>' for d in ['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'])+'</tbody></table>'
    cerca=''.join(f'<li class="relative grid grid-cols-[5rem_1fr] gap-3 py-4 border-t border-ink-200">{pic(i+3,"aspect-square",i!=2,False)}<div><p class="kicker text-ink-500">[600 m] · Alta Córdoba</p><a href="#" class="font-display text-lg leading-tight after:absolute after:inset-0">{N[i+2]}</a><div>{rating(4.3,80)}</div></div></li>' for i in (1,2,3))
    if m:
        ubic=f'<section class="grid md:grid-cols-2 gap-8"><div><p class="kicker text-brand-800">02</p><h2 class="font-display text-3xl font-medium mb-3">Ubicación</h2>{mapa("aspect-[4/3]",False,np=1)}<p class="mt-3 flex gap-2 text-sm">{I("pin","w-4 h-4 text-ink-500 mt-0.5")}[Calle 123, Alta Córdoba]</p></div><div class="md:pt-12"><dl class="border-t border-ink-900/80 text-sm">'+''.join(f'<div class="grid grid-cols-[1.5rem_1fr] gap-2 py-3 border-b border-ink-200"><span class="text-ink-500">{I(ic,"w-4 h-4 mt-0.5")}</span><div><dt class="kicker text-ink-500">{k}</dt><dd class="{c}">{val}</dd></div></div>' for ic,k,val,c in [('phone','Teléfono','<a class="ulink num font-bold" href="#">[0351 000-0000]</a>',''),('clock','Horarios','No informado',"text-ink-500"),('globe','Sitio web','No informado',"text-ink-500")])+f'</dl><p class="mt-2">{G}</p></div></section>'
    else:
        ubic=f'<section class="grid md:grid-cols-2 gap-8"><div><p class="kicker text-brand-800">03</p><h2 class="font-display text-3xl font-medium mb-3">Ubicación</h2>{mapa("aspect-[4/3]",False)}<p class="mt-3 flex gap-2 text-sm">{I("pin","w-4 h-4 text-ink-500 mt-0.5")}[Calle 123, Alta Córdoba]</p></div><div><p class="kicker text-brand-800">04</p><h2 class="font-display text-3xl font-medium mb-3">Horarios</h2>{hrs}<p class="mt-2">{G}</p></div></section>'
    hero=pic(1,"w-full aspect-[4/3] md:aspect-[16/10]",v)
